<article class="news-card"><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail()) the_post_thumbnail('large',['loading'=>'lazy']); ?></a><div><div class="eyebrow"><?php echo ma_theme_location_label(); ?> · <?php $c=get_the_category(); echo esc_html($c[0]->name??'Aktuell'); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php if(has_excerpt()): ?><p><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><div class="meta-line"><span><?php echo esc_html(get_the_date('d.m.Y · H:i')); ?> Uhr</span><a href="<?php the_permalink(); ?>#comments"><?php echo (int)get_comments_number(); ?> Kommentare</a></div><a class="read-more" href="<?php the_permalink(); ?>">Mehr lesen</a></div></article>
